$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m');$currentMonth=date('Y-m');if($month>$currentMonth)$month=$currentMonth;
$ts=strtotime($month.'-01');if(!$ts){$month=date('Y-m');$ts=strtotime($month.'-01');}$from=$month.'-01';$to=date('Y-m-t',$ts);$prev=date('Y-m',strtotime('-1 month',$ts));$next=date('Y-m',strtotime('+1 month',$ts));$hasNext=$next<=$currentMonth;
