function ei_hm(int $minutes): string {$minutes=max(0,$minutes);return sprintf('%d:%02d',(int)floor($minutes/60),$minutes%60);}
function ei_month_label(int $ts): string {$m=['01'=>'มกราคม','02'=>'กุมภาพันธ์','03'=>'มีนาคม','04'=>'เมษายน','05'=>'พฤษภาคม','06'=>'มิถุนายน','07'=>'กรกฎาคม','08'=>'สิงหาคม','09'=>'กันยายน','10'=>'ตุลาคม','11'=>'พฤศจิกายน','12'=>'ธันวาคม'];$key=date('m',$ts);return ($m[$key]??date('F',$ts)).' '.((int)date('Y',$ts)+543);}
function ei_pay_type(string $type,bool $isPr): string {if($type==='hourly')return 'ตามชั่วโมงทำงาน';if($type==='monthly')return 'เงินเดือนรายเดือน';return $isPr?'ค่ากะ / รายวัน':'ค่าแรงรายวัน';}
